const D = { scale: 1, energy: .62, depth: 6, density: .55, speed: 1, fold: 3, hue: 205, x: .5, y: .5, style: 'spectral', seed: 0, alpha: 100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const TAU = Math.PI * 2;
const u = Math.min(width, height);
const seed = P.seed | 0;
const foldN = Math.max(1, Math.min(6, P.fold | 0));
const NF = 4;                      // families in the morph ring
const maxSeg = 1400;
let edepth = Math.floor(Math.log2(maxSeg / foldN));
edepth = Math.max(2, Math.min(P.depth | 0, edepth, 9));

const fr = i => { const s = Math.sin(i * 127.1 + seed * 311.7) * 43758.5453; return s - Math.floor(s); };

// ---- build & cache family vertex lists (de Rham / Cesaro single-insert subdivision) ----
const cacheKey = seed + '|' + edepth + '|' + foldN;
if (S.cacheKey !== cacheKey) {
  S.cacheKey = cacheKey;
  S.hoff = fr(99);
  S.rphase = fr(50) * TAU;
  S.bphase = fr(60) * NF;
  const segPer = 1 << edepth;
  const count = foldN * segPer;
  S.count = count;
  const start = -Math.PI / 2;
  // family presets [are, aim, alternate] : koch / levy-C / dragon / spiky
  const base = [ [0.5, 0.29, 0], [0.5, 0.50, 0], [0.5, 0.50, 1], [0.5, 0.20, 1] ];
  function genFamily(are, aim, alt) {
    const out = new Float64Array(count * 2);
    let w = 0;
    for (let e = 0; e < foldN; e++) {
      let ax, ay, bx, by;
      if (foldN === 1) { ax = -1; ay = 0; bx = 1; by = 0; }
      else {
        const a0 = start - e * TAU / foldN, a1 = start - (e + 1) * TAU / foldN;
        ax = Math.cos(a0); ay = Math.sin(a0); bx = Math.cos(a1); by = Math.sin(a1);
      }
      let px = [ax, bx], py = [ay, by];
      for (let lv = 0; lv < edepth; lv++) {
        const nx = [px[0]], ny = [py[0]];
        for (let k = 0; k < px.length - 1; k++) {
          const Ax = px[k], Ay = py[k], Bx = px[k + 1], By = py[k + 1];
          const vx = Bx - Ax, vy = By - Ay;
          const ai = (alt && (k & 1)) ? -aim : aim;
          const cx = Ax + (are * vx - ai * vy);
          const cy = Ay + (are * vy + ai * vx);
          nx.push(cx, Bx); ny.push(cy, By);
        }
        px = nx; py = ny;
      }
      for (let k = 0; k < px.length - 1; k++) { out[w++] = px[k]; out[w++] = py[k]; }
    }
    // normalize to fit [-1,1]
    let mnx=1e9,mny=1e9,mxx=-1e9,mxy=-1e9;
    for (let k=0;k<out.length;k+=2){ if(out[k]<mnx)mnx=out[k]; if(out[k]>mxx)mxx=out[k]; if(out[k+1]<mny)mny=out[k+1]; if(out[k+1]>mxy)mxy=out[k+1]; }
    const ccx=(mnx+mxx)*0.5, ccy=(mny+mxy)*0.5;
    const half=Math.max((mxx-mnx)*0.5,(mxy-mny)*0.5,1e-6);
    for (let k=0;k<out.length;k+=2){ out[k]=(out[k]-ccx)/half; out[k+1]=(out[k+1]-ccy)/half; }
    return out;
  }
  S.fam = [];
  for (let f=0; f<NF; f++){
    const are = Math.max(0.42, Math.min(0.58, base[f][0] + (fr(f*3+10)-0.5)*0.05));
    const aim = Math.max(0.14, Math.min(0.55, base[f][1] + (fr(f*3+20)-0.5)*0.08));
    S.fam.push(genFamily(are, aim, base[f][2]));
  }
  S.buf = new Float64Array(count * 2);
}

const N = S.count, fam = S.fam, buf = S.buf;
const closed = foldN > 1;

// ---- clock motion floor (never re-phases) ----
const spd = P.speed;
const rot = K.t * (0.028 + spd * 0.05) + S.rphase;
const breath = 1 + 0.05*Math.sin(K.t*0.4) + K.swell*0.06 + A.rms*0.10;
const sec = K.section | 0;
let bl = K.t * (0.04 + spd*0.06) + S.bphase + sec*0.5;
bl = ((bl % NF) + NF) % NF;
const i0 = Math.floor(bl) % NF, i1 = (i0+1) % NF, mixf = bl - Math.floor(bl);
const fa = fam[i0], fb = fam[i1];
for (let k=0;k<N*2;k++) buf[k] = fa[k] + (fb[k]-fa[k])*mixf;

// ---- palette / exposure ----
const glow = P.energy*(0.55+K.intensity*0.5) + A.rms*0.5 + K.swell*0.15 + K.pulse*0.25;
const hb = (((P.hue + S.hoff*30 + sec*15 + K.t*1.4) % 360) + 360) % 360;
const aif = P.alpha/100;
const radius = u * 0.44 * P.scale * breath;
const cx = P.x*width, cy = P.y*height;
const style = P.style;

// per-style config
let ST;
if (style === 'gold')
  ST = { grndH:38, grndS:42, grndB:14, coreW: Math.max(2, u*0.0040), haloW: u*0.026, halo2W: u*0.011, haloA:11, halo2A:20, coreA:100, fillH:40, fillS:60, fillB:60, fillA:11, bloomA:9, bloomH:42, mode:'gold' };
else if (style === 'neon')
  ST = { grndH:hb, grndS:60, grndB:9,  coreW: Math.max(2, u*0.0036), haloW: u*0.030, halo2W: u*0.013, haloA:15, halo2A:24, coreA:100, fillH:hb, fillS:80, fillB:55, fillA:8, bloomA:12, bloomH:hb, mode:'neon' };
else if (style === 'blueprint')
  ST = { grndH:212, grndS:70, grndB:26, coreW: Math.max(1.4, u*0.0018), haloW:0, halo2W:0, haloA:0, halo2A:0, coreA:96, fillH:200, fillS:38, fillB:72, fillA:6, bloomA:0, bloomH:200, mode:'blueprint' };
else if (style === 'ink')
  ST = { grndH:40, grndS:12, grndB:88, coreW: Math.max(2.6, u*0.0060), haloW:0, halo2W:0, haloA:0, halo2A:0, coreA:84, fillH:32, fillS:20, fillB:32, fillA:10, bloomA:0, bloomH:32, mode:'ink' };
else
  ST = { grndH:hb, grndS:48, grndB:18, coreW: Math.max(2, u*0.0038*(0.7+P.density*0.7)), haloW: u*0.024*(0.6+P.density*0.8), halo2W: u*0.010, haloA:11, halo2A:20, coreA:100, fillH:hb, fillS:66, fillB:56, fillA:9, bloomA:12, bloomH:hb, mode:'spectral' };

// ---- ground (fills the frame; never near-black at default) ----
if (P.alpha >= 100) {
  background(ST.grndH, ST.grndS, ST.grndB + 3*K.intensity);
} else {
  noStroke();
  fill(ST.grndH, ST.grndS, ST.grndB, 16*aif);
  rect(0,0,width,height);
}

// ---- broad central bloom (lifts luminance, glow styles only) ----
if (ST.bloomA > 0 && P.alpha >= 100) {
  push(); blendMode(ADD); noStroke();
  const gr = u*(0.5 + P.density*0.35);
  const ga = ST.bloomA*(0.7 + glow*0.9);
  for (let r=0;r<5;r++){ fill(ST.bloomH, 55 - r*7, 45 + r*11, ga*(1 - r*0.18)); const rr = gr*(2.4 - r*0.42); ellipse(cx, cy, rr, rr); }
  blendMode(BLEND); pop();
}

push();
translate(cx, cy);
rotate(rot);

// faint luminous interior fill -> reads as a solid form, not a thread
if (ST.fillA > 0 && closed) {
  noStroke();
  fill(ST.fillH, ST.fillS, ST.fillB, ST.fillA*aif*(0.7+0.4*K.intensity));
  beginShape();
  for (let k=0;k<N;k++) vertex(buf[k*2]*radius, buf[k*2+1]*radius);
  endShape(CLOSE);
}

// wide ADD glow halo (the "thick glowing line" outer bloom)
if (ST.haloA > 0) {
  blendMode(ADD); noFill(); strokeCap(ROUND); strokeJoin(ROUND);
  stroke(ST.bloomH, ST.mode==='spectral'?70:ST.grndS, 92, ST.haloA*(0.7+glow*0.7)*aif);
  strokeWeight(ST.haloW*(0.85 + A.bass*0.5));
  beginShape(); for (let k=0;k<N;k++) vertex(buf[k*2]*radius, buf[k*2+1]*radius); if (closed) endShape(CLOSE); else endShape();
  blendMode(BLEND);
}
if (ST.halo2A > 0) {
  blendMode(ADD); noFill(); strokeCap(ROUND); strokeJoin(ROUND);
  stroke(ST.bloomH, 50, 100, ST.halo2A*(0.7+glow*0.6)*aif);
  strokeWeight(ST.halo2W);
  beginShape(); for (let k=0;k<N;k++) vertex(buf[k*2]*radius, buf[k*2+1]*radius); if (closed) endShape(CLOSE); else endShape();
  blendMode(BLEND);
}

// core -- thick hue-gradient line along the curve length
noFill(); strokeCap(ROUND); strokeJoin(ROUND);
strokeWeight(ST.coreW*(1 + A.bass*0.4));
const gph = rot*0.3 + K.t*0.25;
const H = 44;
for (let m=0;m<H;m++){
  const a0 = Math.floor(m*N/H);
  let a1 = Math.floor((m+1)*N/H);
  if (a1 >= N) a1 = closed ? N : N-1;
  const g01 = m/H;
  let hh, ss, bb;
  const aa = ST.coreA*aif;
  if (ST.mode==='gold'){ const sh=(Math.sin(g01*TAU*2+gph)+1)*0.5; hh=38+8*sh; ss=85-32*sh; bb=52+48*sh; }
  else if (ST.mode==='neon'){ hh=hb+22*Math.sin(g01*TAU+gph); ss=92-30*Math.abs(Math.sin(g01*Math.PI+gph)); bb=100; }
  else if (ST.mode==='blueprint'){ hh=198+8*Math.sin(g01*TAU); ss=28+18*Math.sin(g01*TAU*2); bb=100; }
  else if (ST.mode==='ink'){ hh=32; ss=16; bb=14+8*Math.sin(g01*TAU+gph); }
  else { hh=hb + 300*g01 + 40*Math.sin(g01*TAU+gph); ss=88; bb=88+12*Math.sin(g01*TAU+gph*1.2); }
  stroke(((hh%360)+360)%360, ss, bb, aa);
  beginShape(); for (let k=a0;k<=a1;k++){ const kk=k%N; vertex(buf[kk*2]*radius, buf[kk*2+1]*radius); } endShape();
}

pop();
blendMode(BLEND);
